import { readFile, writeFile } from "node:fs/promises";

const manifest = JSON.parse(await readFile(new URL("../deployments/monad-testnet.json", import.meta.url), "utf8"));
await writeFile(new URL("../packages/sdk/src/deployment.ts", import.meta.url),
  "// Generated by scripts/generate-sdk-contracts.mjs. Do not edit independently.\n" +
  `export const monadTestnetDeployment = ${JSON.stringify(manifest, null, 2)} as const;\n`);
let abiSource = "// Generated from the unchanged Foundry contract artifacts.\n";
for (const name of Object.keys(manifest.contracts)) {
  const { abi } = JSON.parse(await readFile(new URL(`../contracts/out/${name}.sol/${name}.json`, import.meta.url), "utf8"));
  abiSource += `export const ${name[0].toLowerCase() + name.slice(1)}Abi = ${JSON.stringify(abi)} as const;\n`;
}
await writeFile(new URL("../packages/sdk/src/abis.ts", import.meta.url), abiSource);
